import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { MdMenu, MdNotifications, MdAccountCircle, MdLogout, MdSettings } from 'react-icons/md';
import { useAuth } from '../../context/AuthContext';
import './Navbar.css';

const Navbar = ({ toggleSidebar }) => {
  const { admin, logout } = useAuth();
  const navigate = useNavigate();
  const [dropdownOpen, setDropdownOpen] = useState(false);

  const handleLogout = () => {
    logout();
    navigate('/login');
  };

  return (
    <header className="navbar">
      <div className="navbar-left">
        <button className="menu-btn" onClick={toggleSidebar} aria-label="Toggle sidebar">
          <MdMenu />
        </button>
        <div className="breadcrumb">
          <span>Welcome back,</span>
          <strong>{admin?.name || 'Admin'}</strong>
        </div>
      </div>

      <div className="navbar-right">
        <button className="icon-btn" aria-label="Notifications">
          <MdNotifications />
          <span className="badge">3</span>
        </button>

        <div className="profile-wrapper">
          <button
            className="profile-btn"
            onClick={() => setDropdownOpen(!dropdownOpen)}
            aria-label="Profile menu"
          >
            <div className="avatar">
              {admin?.name?.charAt(0).toUpperCase() || 'A'}
            </div>
            <div className="profile-info">
              <span className="profile-name">{admin?.name || 'Admin'}</span>
              <span className="profile-email">{admin?.email}</span>
            </div>
          </button>

          {dropdownOpen && (
            <div className="dropdown-menu">
              <div className="dropdown-header">
                <div className="dropdown-avatar">
                  {admin?.name?.charAt(0).toUpperCase() || 'A'}
                </div>
                <div>
                  <p className="dropdown-name">{admin?.name}</p>
                  <p className="dropdown-email">{admin?.email}</p>
                </div>
              </div>
              <hr className="dropdown-divider" />
              <button className="dropdown-item">
                <MdSettings /> Settings
              </button>
              <button className="dropdown-item logout" onClick={handleLogout}>
                <MdLogout /> Logout
              </button>
            </div>
          )}
        </div>
      </div>

      {dropdownOpen && (
        <div className="dropdown-overlay" onClick={() => setDropdownOpen(false)} />
      )}
    </header>
  );
};

export default Navbar;
